def main():
    rs=[load(k) for k in KEYS];raw=rs[0]['raw'];pairs=json.loads((HERE/'comparisons.json').read_text());fig=HERE/'figures';fig.mkdir(exist_ok=True)
    plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'white'})
    def save(f,name):f.tight_layout();f.savefig(fig/name,dpi=180,bbox_inches='tight');plt.close(f)
    f,ax=plt.subplots(figsize=(10,4));vals=[raw['biological_miou']]+[r['wcsp']['biological_miou'] for r in rs];bars=ax.bar(['Raw TP']+LABELS,vals,color=['#8394a1','#a0aeb5','#326899','#169b87']);ax.set_ylim(0,.58);ax.set_ylabel('Pooled biological mIoU')
