        d=row['wcsp']['biological_miou']-bypot[i]['wcsp']['biological_miou'];f.suptitle(f'Fold 2 / {i:04d} - {row["tissue"]}; biological minus Potts patch mIoU {d:+.6f}');f.legend(handles=[Patch(color=c,label=n) for c,n in zip(COLORS,CLASSES)],loc='lower center',ncol=6,fontsize=9);f.tight_layout(rect=[0,.12,1,.9]);f.savefig(fig/(kind+'.png'),dpi=180);plt.close(f);examples[kind]=dict(image_index=i,tissue=row['tissue'],delta=d)
